function createPr459Fixture() {
  const contentByPath = new Map();
  const files = PR459_PINNED_PAYLOAD.map((expected) => {
    const packed = PR459_CONTENT_GZIP_BASE64[expected.path];
    assert.equal(typeof packed, 'string', `fixture missing ${expected.path}`);
    const bytes = gunzipSync(Buffer.from(packed, 'base64'));
    assert.equal(createHash('sha256').update(bytes).digest('hex'), expected.sha256);
    const blobSha = gitBlobSha(bytes);
    contentByPath.set(expected.path, {
      type: 'file',
      path: expected.path,
      encoding: 'base64',
      content: bytes.toString('base64'),
      size: bytes.length,
      sha: blobSha,
    });
    return { status: expected.status, filename: expected.path, sha: blobSha };
  });
  return { files, contentByPath };
}

function createMutatedPr459Fixture(targetPath) {
  const fixture = createPr459Fixture();
  const original = fixture.contentByPath.get(targetPath);
  const changed = Buffer.concat([Buffer.from(original.content, 'base64'), Buffer.from('x')]);
  const replacement = {
    ...original,
    content: changed.toString('base64'),
    size: changed.length,
    sha: gitBlobSha(changed),
  };
  fixture.contentByPath.set(targetPath, replacement);
  fixture.files = fixture.files.map((file) =>
    file.filename === targetPath ? { ...file, sha: replacement.sha } : file,
  );
  return fixture;
}

