    pr459PositiveTest('PR459 POS 07 ordinal ordering is deterministic', () => {
      const records = [
        { path: 'ä', sha256: '3' },
        { path: 'a', sha256: '2' },
        { path: 'Z', sha256: '1' },
      ];
      const ordered = [...records].sort((a, b) => compareOrdinalCodePoints(a.path, b.path));
      assert.deepEqual(ordered.map((record) => record.path), ['Z', 'a', 'ä']);
      const explicit = createHash('sha256')
        .update('Z\t1\na\t2\nä\t3', 'utf8')
        .digest('hex');
      assert.equal(computeCanonicalPayloadDigest(records), explicit);
    });

